import{n as t}from"./shared-CAKwAg2C.js";const n={"LEARN HOW THE INTERNET WORKS":"COMO A INTERNET FUNCIONA","NOW LEARNING":"APRENDENDO","OSI LAYER":"CAMADA OSI","LEARNING PROGRESS":"SEU PROGRESSO",COMPLETE:"CONCLUÍDOS","IN PROGRESS":"EM CURSO","{pct}% complete":"{pct}% concluído","DESIGNED BY":"CRIADO POR","Dilum Sanjaya on X":"Dilum Sanjaya no X","Layer {n}: {name}":"Camada {n}: {name}",Physical:"Física","Data Link":"Enlace de dados",Network:"Rede",Transport:"Transporte",Session:"Sessão",Presentation:"Apresentação",Application:"Aplicação","OVERVIEW · {n} STEPS":"VISÃO GERAL · {n} PASSOS","STEP {n}/{total} · {title}":"PASSO {n}/{total} · {title}","LESSON COMPLETE":"LIÇÃO CONCLUÍDA",PROTOCOLS:"PROTOCOLOS",Protocols:"Protocolos",Language:"Idioma",Theme:"Tema","Light mode":"Modo claro","Dark mode":"Modo escuro","INTERNET PROTOCOLS":"PROTOCOLOS DE INTERNET",More:"Mais","Close the protocol list":"Fechar a lista de protocolos","Close (Esc)":"Fechar (Esc)",ALL:"TODOS",CORE:"BASE",APPLICATION:"APLICAÇÃO",SECURITY:"SEGURANÇA",NETWORK:"REDE",SEQUENCE:"SEQUÊNCIA",View:"Visualização","Switch view (V)":"Trocar de visualização (V)","Network diagram":"Diagrama de rede","Sequence diagram":"Diagrama de sequência","STEP {n}":"PASSO {n}","PROTOCOL OVERVIEW":"VISÃO GERAL","STEP DETAILS":"PASSO ATUAL","LESSON SUMMARY":"RESUMO",OVERVIEW:"INÍCIO",ACTIVE:"ATIVO","STEP {n} OF {total}":"PASSO {n} DE {total}","PACKET {n} OF {total}":"PACOTE {n} DE {total}","PACKETS {from}–{to} OF {total}":"PACOTES {from}–{to} DE {total}","{n} LOST":"{n} PERDIDOS","1 LOST":"1 PERDIDO",ENCRYPTED:"CRIPTOGRAFADO","LOST ON THE WAY":"PERDIDO NO CAMINHO","PACKET FLOW":"FLUXO DE PACOTES","Colour key":"Legenda de cores","Playback speed":"Velocidade de reprodução","Previous step (←)":"Passo anterior (←)","Previous step":"Passo anterior","Play / pause (Space)":"Reproduzir / pausar (Espaço)",PLAY:"REPRODUZIR",PAUSE:"PAUSAR",REPLAY:"REPETIR",STEP:"PASSO","One packet at a time":"Um pacote por vez",RESET:"REINICIAR",Reset:"Reiniciar","Back to the overview (Esc)":"Voltar à visão geral (Esc)","NO.":"Nº",TIME:"TEMPO",SOURCE:"ORIGEM",DESTINATION:"DESTINO",PROTOCOL:"PROTOCOLO",INFO:"INFO",SIZE:"TAMANHO","No packets on the wire yet.":"Ainda não há pacotes na rede.",LOST:"PERDIDO","Packet inspector":"Inspetor de pacotes","Previous packet":"Pacote anterior","Previous packet (←)":"Pacote anterior (←)","Next packet":"Próximo pacote","Next packet (→)":"Próximo pacote (→)",Close:"Fechar","E.G.":"EX.","an example value: it differs in every real capture":"um valor de exemplo: muda em cada captura real","bytes the lesson can’t show: encrypted, random, or a file’s contents":"bytes que a lição não pode mostrar: criptografados, aleatórios ou o conteúdo de um arquivo",BYTES:"BYTES","{n} in this frame":"{n} neste quadro","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Esta linha representa {n} segmentos TCP que levam uma mensagem de {size} bytes; o primeiro segmento é mostrado","This packet was lost on the way":"Este pacote se perdeu no caminho",Padding:"Preenchimento","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · CONCESSÃO 24 H","2 SEGMENTS":"2 SEGMENTOS","3 SEGMENTS":"3 SEGMENTOS","3 DATAGRAMS":"3 DATAGRAMAS","4 DATAGRAMS":"4 DATAGRAMAS","203.0.113.10 IS NOT LOCAL":"203.0.113.10 NÃO É LOCAL","250 QUEUED":"250 NA FILA",ANSWER:"RESPOSTA","APP COVERS THE 20 MS GAP":"O APP COBRE A LACUNA DE 20 MS","APP DATA":"DADOS DO APP","ARP REPLY":"RESPOSTA ARP","ARP REQUEST":"REQUISIÇÃO ARP","ARRIVED WITH TTL 116":"CHEGOU COM TTL 116","AUTH FAILURE":"FALHA DE AUTH","At QUIT":"No QUIT","CACHED · TTL 3600 S":"EM CACHE · TTL 3600 S","CERTIFICATE VALID":"CERTIFICADO VÁLIDO","CHAIN LEADS TO A TRUSTED ROOT":"A CADEIA LEVA A UMA RAIZ CONFIÁVEL","CHANNEL OPEN":"ABRIR CANAL",CONFIRMED:"CONFIRMADO","DNS QUERY":"CONSULTA DNS","DNS REPLY":"RESPOSTA DNS","DUP ACK":"ACK DUPLICADO","EACH KEY IS ITS OWN PACKET":"CADA TECLA, UM PACOTE",ECHO:"ECO","ECHO REPLY":"RESPOSTA DE ECO","ECHO REQUEST":"REQUISIÇÃO DE ECO",ENTER:"ENTER","FRAME 7 LOST · NOT RESENT":"QUADRO 7 PERDIDO · NÃO REENVIADO","HOP 2 · 198.51.100.1":"SALTO 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"CHAVE DE HOST CONFERE COM KNOWN_HOSTS","IN BOB’S MAILBOX":"NA CAIXA DE ENTRADA DE BOB","IP PACKET":"PACOTE IP",MESSAGE:"MENSAGEM","MESSAGE 1 DELETED":"MENSAGEM 1 EXCLUÍDA","NEW MAIL ARRIVED":"CHEGOU E-MAIL NOVO","NO IP ADDRESS YET":"AINDA SEM ENDEREÇO IP","NOT IN CACHE":"FORA DO CACHE","OFFER KEY":"OFERECE CHAVE",OUTPUT:"SAÍDA","PASSWORD IN PLAIN TEXT":"SENHA EM TEXTO PURO",REFERRAL:"REFERÊNCIA",REPLY:"RESPOSTA",RESEND:"REENVIO","SEGMENT 1 LOST":"SEGMENTO 1 PERDIDO","SFTP or FTPS":"SFTP ou FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP, ou FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"SEGREDO COMPARTILHADO CALCULADO",SIGNED:"ASSINADO","STILL ON SERVER · \\SEEN":"AINDA NO SERVIDOR · \\SEEN",SUCCESS:"SUCESSO","TIME EXCEEDED":"TEMPO EXCEDIDO","TIME=34MS TTL=52":"TEMPO=34MS TTL=52",UNREACHABLE:"INALCANÇÁVEL",VERSION:"VERSÃO","VOICE 1":"VOZ 1","+OK or -ERR":"+OK ou -ERR",".com Server":"Servidor .com",Authoritative:"Autoritativo","Log In":"Fazer login",Key:"Chave",Why:"Por quê",End:"Fim","MACs, in":"MACs, entrada",Internet:"Internet",Router:"Roteador","Router 192.168.1.1":"Roteador 192.168.1.1","Router: 192.168.1.1":"Roteador: 192.168.1.1",Routers:"Roteadores",Hardware:"Hardware",Audio:"Áudio",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic cookie",Visible:"Visível",Tickets:"Tickets","4, 20 bytes":"4, 20 bytes","20–60 bytes":"20–60 bytes","20–60 bytes (IPv4)":"20–60 bytes (IPv4)","8 bytes (TCP: 20+)":"8 bytes (TCP: 20+)","32 bytes (Windows)":"32 bytes (Windows)","1,460 bytes (MSS)":"1,460 bytes (MSS)","78 bytes (seq 1–78)":"78 bytes (seq 1–78)","bytes 1461–2920":"bytes 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 bytes)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 bytes)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 bytes), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 bytes)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 bytes)',"32 bits (IPv4), 128 (IPv6)":"32 bits (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 → 52 (12 roteadores)","52 (64 − 12 routers)":"52 (64 − 12 roteadores)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 bytes","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 bytes (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + áudio"},i={"Hypertext Transfer Protocol":"Transferência de hipertexto","HTTP Secure":"HTTP seguro","Transmission Control Protocol":"Controle de transmissão","User Datagram Protocol":"Datagramas de usuário","Internet Protocol":"Protocolo de internet","Domain Name System":"Sistema de nomes de domínio","Dynamic Host Configuration":"Configuração dinâmica de host","Internet Control Message":"Mensagens de controle da internet","Simple Mail Transfer Protocol":"Transferência simples de e-mail","Post Office Protocol v3":"Protocolo de agência de correio v3","Internet Message Access":"Acesso a mensagens da internet","File Transfer Protocol":"Transferência de arquivos","Secure Shell":"Shell seguro","Transport Layer Security":"Segurança da camada de transporte",Internet:"Internet",Client:"Cliente",Router:"Roteador","DNS Resolver":"Resolvedor DNS","Web Server":"Servidor web","Root Server":"Servidor raiz",".com TLD Server":"Servidor TLD .com","Authoritative Server":"Servidor autoritativo","Mail Server":"Servidor de e-mail","Web Communication":"Comunicação web",Request:"Requisição",Response:"Resposta","Data ACKs not shown":"ACKs de dados não mostrados","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP é o protocolo da web: um cliente pede um recurso, como uma página HTML, e o servidor responde com um código de status, cabeçalhos e geralmente um corpo. Cada troca é uma requisição e uma resposta, escritas como texto legível no HTTP/1.1.",Layer:"Camada","Application (Layer 7)":"Aplicação (camada 7)","Default Port":"Porta padrão",Transport:"Transporte","Data Format":"Formato dos dados","Text (headers + optional body)":"Texto (cabeçalhos + corpo opcional)","Common Methods":"Métodos comuns","Defined In":"Definido em","Page delivered":"Página entregue","One request, one response":"Uma requisição, uma resposta","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"Em menos de um décimo de segundo, o notebook buscou um endereço, abriu uma conexão TCP e trocou uma requisição e uma resposta HTTP, tudo legível para qualquer um no caminho. Pressione REPETIR para ver de novo.","Round trips":"Idas e voltas","Total time":"Tempo total","Page size":"Tamanho da página","Sent as 9 TCP segments":"Enviada em 9 segmentos TCP","Client Request":"Requisição do cliente","Browser prepares the request":"O navegador prepara a requisição","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Você abre http://www.example.com. O navegador vai enviar uma requisição GET, mas os pacotes viajam para endereços IP, não para nomes, então primeiro ele precisa do endereço do servidor. (Hoje os navegadores tentam https:// primeiro; esta é a versão sem criptografia.)",Method:"Método","Next hop":"Próximo salto","Router 192.168.1.1":"Roteador 192.168.1.1","DNS Resolution":"Resolução DNS","Finds the server’s IP address":"Encontra o endereço IP do servidor","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"O notebook pergunta ao servidor DNS que recebeu do DHCP, 8.8.8.8, qual é o endereço de www.example.com. A consulta vai pela porta UDP 53 e a resposta é um registro A com o endereço IPv4. (Numa rede com IPv6 ele também pediria um registro AAAA.)",Resolver:"Resolvedor","8.8.8.8 (had it cached)":"8.8.8.8 (estava em cache)","UDP, port 53":"UDP, porta 53",Answer:"Resposta","TCP Connection":"Conexão TCP","Establishes a reliable link":"Estabelece um enlace confiável","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"O HTTP roda sobre o TCP. Antes de qualquer dado da página circular, o notebook e o servidor abrem uma conexão com a porta 80 por meio de um handshake de três vias: SYN, SYN-ACK, ACK.","Server port":"Porta do servidor","Client port":"Porta do cliente",Handshake:"Handshake","HTTP Exchange":"Troca HTTP","Request and response messages":"Mensagens de requisição e resposta","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"O navegador envia uma requisição GET com um cabeçalho Host. O servidor responde 200 OK com o HTML no corpo: 12.2 KB, grande demais para um só pacote, então o TCP o divide em 9 segmentos de até 1460 bytes (aqui desenhados como um).",Status:"Status",Body:"Corpo","Sent as":"Enviada em","12.2 KB in 9 segments":"12.2 KB em 9 segmentos","Page Rendering":"Renderização da página","Browser displays the content":"O navegador exibe o conteúdo","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"O navegador analisa o HTML e desenha a página. Cada CSS, imagem ou script vinculado iniciaria mais requisições como esta, reutilizando a conexão aberta quando possível.",Document:"Documento",Connection:"Conexão","Kept open for reuse":"Mantida aberta para reúso","Seen on the laptop’s home network":"Visto na rede doméstica do notebook",Destination:"Destino","The router: anything beyond the home network goes to it first.":"O roteador: tudo o que vai além da rede doméstica passa primeiro por ele.",Source:"Origem","The laptop’s network card.":"A placa de rede do notebook.",Type:"Tipo","What the frame carries.":"O que o quadro transporta.","Version, header length":"Versão, tamanho do cabeçalho","IPv4, with no options.":"IPv4, sem opções.","Priority and congestion marks; 0 means ordinary traffic.":"Marcas de prioridade e congestionamento; 0 significa tráfego comum.","Total length":"Tamanho total","This header and everything inside it.":"Este cabeçalho e tudo o que há dentro dele.",Identification:"Identificação","Lets the receiver reassemble the pieces if the packet gets split.":"Permite ao receptor remontar as partes se o pacote for dividido.",Flags:"Flags",none:"nenhuma","Routers may split it if a link is too small.":"Os roteadores podem dividi-lo se um enlace for pequeno demais.","Time to live":"Tempo de vida","Windows starts at 128.":"O Windows começa em 128.",Protocol:"Protocolo","Header checksum":"Checksum do cabeçalho","Covers this header only; every router recomputes it after lowering the TTL.":"Cobre só este cabeçalho; cada roteador o recalcula depois de diminuir o TTL.","Source port":"Porta de origem","Destination port":"Porta de destino",Length:"Tamanho","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"Cabeçalho UDP e dados. Isso é todo o UDP: sem numeração, sem confirmações.",Checksum:"Checksum","Covers the header, the data and the IP addresses.":"Cobre o cabeçalho, os dados e os endereços IP.","Transaction ID":"ID da transação","Picked at random; the answer must carry the same one.":"Escolhido ao acaso; a resposta precisa trazer o mesmo.","0x0100: query, RD (recursion desired)":"0x0100: consulta, RD (recursão desejada)",Questions:"Perguntas",Answers:"Respostas","Authority records":"Registros de autoridade","Additional records":"Registros adicionais",Question:"Pergunta","www.example.com, type A, class IN":"www.example.com, tipo A, classe IN","The laptop.":"O notebook.","The router’s side facing the home network.":"O lado do roteador voltado para a rede doméstica.","Started at 128; 10 routers on the way each took 1.":"Começou em 128; cada um dos 10 roteadores do caminho tirou 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: resposta, RD (recursão desejada), RA (recursão disponível)","DF (don’t fragment)":"DF (não fragmentar)","Routers must not split it; if it’s too big they report back instead.":"Os roteadores não devem dividi-lo; se for grande demais, eles avisam de volta.","Picked by the laptop’s system for this connection.":"Escolhida pelo sistema do notebook para esta conexão.","Sequence number":"Número de sequência","This side’s starting number. Shown as 0; the real one is random.":"O número inicial deste lado. Mostrado como 0; o real é aleatório.","Real sequence number":"Número de sequência real",Acknowledgment:"Confirmação","0 (not used yet)":"0 (ainda não usado)","A first SYN has nothing to acknowledge.":"Um primeiro SYN não tem nada a confirmar.","Header length":"Tamanho do cabeçalho","20 bytes, plus 12 of options.":"20 bytes, mais 12 de opções.",Window:"Janela","How much more data this side can take right now.":"Quantos dados a mais este lado consegue receber agora.","Covers the header, the data and the IP addresses, so damage is caught.":"Cobre o cabeçalho, os dados e os endereços IP, assim danos são detectados.","Urgent pointer":"Ponteiro urgente",Options:"Opções","Maximum segment size":"Tamanho máximo de segmento","The most data this side wants in one segment.":"O máximo de dados que este lado quer num segmento.","Spacing, so the next option lines up.":"Espaçamento, para alinhar a próxima opção.","Window scale":"Escala de janela","Window values are multiplied by this, so windows can be larger than 64 KB.":"Os valores de janela são multiplicados por isto, assim as janelas podem passar de 64 KB.","SACK permitted":"SACK permitido",yes:"sim","This side understands selective acknowledgements.":"Este lado entende confirmações seletivas.","Started at 64; 12 routers on the way each took 1.":"Começou em 64; cada um dos 12 roteadores do caminho tirou 1.","The next byte this side expects: everything before it has arrived.":"O próximo byte que este lado espera: tudo antes dele já chegou.","Position of this segment’s first byte, counted from this side’s SYN.":"Posição do primeiro byte deste segmento, contada a partir do SYN deste lado.",Padding:"Preenchimento","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Quadros Ethernet têm pelo menos 60 bytes (64 com o checksum que a placa adiciona), então os curtos são preenchidos.",Text:"Texto","covers bytes not shown here":"cobre bytes não mostrados aqui","12,500 bytes: the HTML page":"12,500 bytes: a página HTML","The page itself; its contents are not part of the lesson.":"A própria página; o conteúdo dela não faz parte da lição.","Secure Web":"Web segura","TLS handshake":"Handshake TLS","HTTP request":"Requisição HTTP","HTTP response":"Resposta HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS é HTTP enviado por uma conexão TLS criptografada. O TLS prova com um certificado que o servidor é quem diz ser, combina chaves de criptografia novas e depois protege cada requisição e resposta para que ninguém as leia ou altere no caminho.","Application (HTTP over TLS)":"Aplicação (HTTP sobre TLS)",Security:"Segurança","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 ainda é comum)",Proves:"Prova","Server identity (certificate)":"Identidade do servidor (certificado)","Secure page delivered":"Página segura entregue","Encrypted, except the lookup":"Criptografada, exceto a consulta DNS","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"O navegador buscou o endereço com DNS sem criptografia, abriu uma conexão TCP, verificou o certificado do servidor e combinou as chaves em uma única ida e volta. Cada byte HTTP depois disso viajou criptografado. Pressione REPETIR para ver de novo.",Cipher:"Cifra","Still visible":"Ainda visível","IPs, server name, sizes":"IPs, nome do servidor, tamanhos","Secure Request":"Requisição segura","Browser asks for https://":"O navegador pede https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Você digita https://www.example.com. O “s” diz ao navegador para proteger a conexão com TLS, por padrão na porta 443. Antes de conseguir se conectar, ele ainda precisa encontrar o endereço IP do servidor.",Port:"Porta","DNS Lookup":"Consulta DNS","Same lookup as HTTP, not encrypted":"A mesma consulta do HTTP, sem criptografia","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"A consulta é exatamente igual à do HTTP comum: uma pergunta a 8.8.8.8 pela porta UDP 53. Ela não é criptografada, então qualquer um no caminho pode ver qual nome você pediu, a menos que o navegador use DNS sobre HTTPS.",Encrypted:"Criptografado","No (plain DNS)":"Não (DNS sem criptografia)","TCP Handshake":"Handshake TCP","Opens a connection to port 443":"Abre uma conexão com a porta 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"O TLS roda sobre o TCP, então o mesmo handshake de três vias vem primeiro, desta vez para a porta 443. Nada está criptografado ainda.","TLS Handshake":"Handshake TLS","Agrees on keys, checks the certificate":"Combina chaves, verifica o certificado","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"O navegador oferece cifras e partes de chave, incluindo um híbrido pós-quântico. O servidor o escolhe e envia sua própria parte, depois seu certificado, já criptografado. O navegador o confere com as autoridades em que confia.",Version:"Versão","Key exchange":"Troca de chaves","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (híbrido)","Server name":"Nome do servidor","Sent in clear (SNI)":"Enviado às claras (SNI)","key shares: hybrid + x25519":"partes de chave: híbrida + x25519","cipher: AES_128_GCM_SHA256":"cifra: AES_128_GCM_SHA256","then encrypted: cert, Finished":"depois criptografado: cert., Finished","handshake complete (encrypted)":"handshake concluído (criptografado)","Encrypted Exchange":"Troca criptografada","HTTP inside TLS records":"HTTP dentro de registros TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"O GET e o 200 OK são as mesmas mensagens HTTP de antes, lacradas em registros TLS que parecem “dados de aplicação” aleatórios na rede. O servidor também entrega dois tickets de sessão, para que uma visita posterior possa pular parte do handshake.",Inside:"Dentro","GET / and 200 OK":"GET / e 200 OK",Tickets:"Tickets","2, for faster reconnects":"2, para reconectar mais rápido","inside: GET / HTTP/1.1":"dentro: GET / HTTP/1.1","outside: encrypted bytes":"fora: bytes criptografados","inside: HTTP/1.1 200 OK":"dentro: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"fora: 12.9 KB, 9 segmentos","Browser shows the padlock":"O navegador mostra o cadeado","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"O navegador descriptografa a resposta, desenha a página e mostra um cadeado: a conexão é privada e o servidor provou sua identidade. O cabeçalho Strict-Transport-Security diz a ele para usar HTTPS neste site daqui em diante.",Remembers:"Lembra","HTTPS only (HSTS), 1 year":"Só HTTPS (HSTS), 1 ano","Server Hello + encrypted handshake, 3 segments":"Server Hello + handshake criptografado, 3 segmentos","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (criptografado)","Application Data (HTTP request)":"Application Data (requisição HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (criptografado)","Application Data (HTTP response), 9 segments":"Application Data (resposta HTTP), 9 segmentos",Record:"Registro","Content type":"Tipo de conteúdo","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"O registro de um Client Hello diz TLS 1.0 para que middleboxes antigos o deixem passar; as versões reais são oferecidas dentro.","Handshake type":"Tipo de handshake",Contents:"Conteúdo","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Tudo o que o navegador suporta. Os navegadores variam alguns detalhes de uma conexão para outra.","Server name (SNI)":"Nome do servidor (SNI)","Versions offered":"Versões oferecidas","Key shares":"Partes de chave","App protocols (ALPN)":"Protocolos de aplicação (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"Registros TLS 1.3 dizem 1.2 por fora, por compatibilidade.","The server’s choices and its half of the hybrid key exchange.":"As escolhas do servidor e a metade dele da troca de chaves híbrida.","Cipher suite":"Conjunto de cifras","Key share":"Parte de chave","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"Não tem função no TLS 1.3; é enviado para que middleboxes vejam um handshake familiar.","Every encrypted record says Application Data on the outside; the real type is inside.":"Todo registro criptografado diz Application Data por fora; o tipo real fica dentro.","Encrypted data":"Dados criptografados","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Texto cifrado, terminando com uma tag de 16 bytes que denuncia qualquer alteração. Só as duas pontas conseguem lê-lo.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (a cadeia), Certificate Verify (a assinatura), Finished","Finished: a check value over the whole handshake":"Finished: um valor de verificação de todo o handshake","The HTTP request":"A requisição HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket: permite retomar a sessão numa visita posterior","The HTTP response, then the 12,500-byte page":"A resposta HTTP e depois a página de 12,500 bytes","Reliable Delivery":"Entrega confiável","Handshake and ACKs":"Handshake e ACKs","Data from laptop":"Dados do notebook","Data from server":"Dados do servidor","Closing (FIN)":"Encerramento (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"O TCP transforma a entrega de pacotes de “melhor esforço” da internet em um fluxo de bytes confiável e ordenado. Ele numera cada byte, confirma o que chega, reenvia o que se perde e controla o ritmo do remetente para não sobrecarregar nem o outro lado nem a rede.","Transport (Layer 4)":"Transporte (camada 4)","Three-way handshake":"Handshake de três vias",Reliability:"Confiabilidade","Sequence numbers + ACKs":"Números de sequência + ACKs",Recovery:"Recuperação",Retransmission:"Retransmissão",Header:"Cabeçalho","Connection closed":"Conexão encerrada","Every byte accounted for":"Cada byte contabilizado","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"O TCP abriu uma conexão, numerou e confirmou cada byte, notou uma lacuna e reenviou só o segmento que faltava, depois fechou os dois sentidos de forma limpa. O curl recebeu todos os bytes em ordem e nunca percebeu a perda. Pressione REPETIR para ver de novo.",Segments:"Segmentos","14 (1 lost, 1 resent)":"14 (1 perdido, 1 reenviado)","Bytes delivered":"Bytes entregues","78 up, 2,920 down":"78 de subida, 2,920 de descida","Loss found by":"Perda detectada por","Duplicate ACK + SACK":"ACK duplicado + SACK","Open Connection":"Abrir a conexão","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"O curl já sabe o endereço do servidor. Antes de qualquer dado circular, os dois lados escolhem um número de sequência inicial e o confirmam: SYN, SYN-ACK, ACK. Os números aqui são relativos; os reais começam num valor aleatório.",Server:"Servidor","203.0.113.10, port 80":"203.0.113.10, porta 80","Send Data":"Enviar dados","Every byte is numbered":"Cada byte é numerado","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"O curl envia sua requisição HTTP de 78 bytes: os bytes 1 a 78. O número de ACK do servidor, 79, é o próximo byte que ele espera, o que significa que tudo antes dele chegou.",Sent:"Enviado","79 = next byte expected":"79 = próximo byte esperado","Two Segments Back":"Dois segmentos de volta","One of them is lost":"Um deles se perde","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"O servidor responde com 2,920 bytes: dois segmentos cheios de 1,460 bytes, o máximo que cabe num pacote aqui, enviados em sequência. O primeiro se perde em algum ponto da internet; o segundo chega.","Segment 1":"Segmento 1","bytes 1–1460 (lost)":"bytes 1–1460 (perdido)","Segment 2":"Segmento 2","Segment size":"Tamanho do segmento","seq=1 and seq=1461":"seq=1 e seq=1461","the first is lost":"o primeiro se perde","A Gap Is Noticed":"Uma lacuna é notada","Duplicate ACK with SACK":"ACK duplicado com SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Os bytes 1461–2920 chegam, mas os 1–1460 nunca chegaram. Um ACK só pode contar bytes recebidos em ordem, então o notebook repete o ACK 1 na hora e acrescenta um bloco SACK dizendo que já tem 1461–2920.","1 (still waiting for byte 1)":"1 (ainda esperando o byte 1)","holds bytes 1461–2920":"tem os bytes 1461–2920","At once, not delayed":"Na hora, sem atraso","sack: has 1461–2920":"sack: tem 1461–2920","Resend the Gap":"Reenviar a lacuna","Only the missing bytes":"Só os bytes que faltam","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"O SACK diz ao servidor exatamente o que falta, então ele reenvia só o segmento 1, e o notebook confirma tudo. Se nenhum ACK tivesse voltado, os temporizadores entrariam em ação: primeiro uma sondagem depois de cerca de duas idas e voltas, depois o tempo limite de retransmissão (pelo menos 200 ms no Linux).",Resent:"Reenviado","bytes 1–1460 only":"só os bytes 1–1460","Next ACK":"Próximo ACK","2921 (everything)":"2921 (tudo)","curl saw":"O curl viu","Every byte, in order":"Todos os bytes, em ordem","just the missing segment":"só o segmento que falta","Close Connection":"Encerrar a conexão","Each side says goodbye":"Cada lado se despede","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"O curl terminou, então fecha. Cada sentido fecha por conta própria: o notebook envia FIN e o servidor o confirma; depois o servidor envia o próprio FIN e o notebook o confirma. O notebook guarda os dados da conexão por um tempo (TIME-WAIT).","Closed by":"Encerrada por","A FIN from each side":"Um FIN de cada lado",Order:"Ordem",Then:"Depois","Laptop waits (TIME-WAIT)":"O notebook espera (TIME-WAIT)",Data:"Dados","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 bytes: a resposta HTTP, bytes 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 bytes: a resposta HTTP, bytes 1461–2920","has 1461–2920":"tem 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Bytes que chegaram depois da lacuna, então só a lacuna precisa ser reenviada.","Fast Datagrams":"Datagramas rápidos","Your voice":"Sua voz","Their voice":"Voz do outro","Media Server":"Servidor de mídia","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"O UDP envia dados em pacotes independentes chamados datagramas, sem conexão, sem confirmações e sem reenvios. Isso o mantém rápido e leve: ideal para voz, vídeo, jogos e DNS, em que uma resposta atrasada é pior do que uma que falta.",None:"Nenhuma","None (no ACKs, no resends)":"Nenhuma (sem ACKs, sem reenvios)",Ordering:"Ordem","Not guaranteed":"Não garantida","Call keeps flowing":"A chamada continua","Fast, simple, no guarantees":"Rápido, simples, sem garantias","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"O áudio começou já com o primeiro pacote, cada datagrama viajou por conta própria, e o que se perdeu simplesmente sumiu: o UDP nem percebeu. O app cobriu a lacuna e a chamada seguiu. Pressione REPETIR para ver de novo.",Datagrams:"Datagramas","11 (1 lost, never resent)":"11 (1 perdido, nunca reenviado)","Setup time":"Tempo de estabelecimento","0 ms (no handshake)":"0 ms (sem handshake)",Shown:"Mostrado","The first 0.2 s of a call":"Os primeiros 0.2 s de uma chamada","Send Right Away":"Enviar na hora","No handshake, data goes first":"Sem handshake, os dados vão primeiro","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Um app de chamadas já conhece o endereço e a porta do servidor de mídia desde o login. Ele não abre conexão: o primeiro datagrama já leva 20 ms da sua voz, atrás de um cabeçalho UDP de 8 bytes.",Setup:"Estabelecimento",Ports:"Portas","92 B of audio, no setup":"92 B de áudio, sem estabelecimento","A Stream of Datagrams":"Um fluxo de datagramas","One every 20 ms, each on its own":"Um a cada 20 ms, cada um por conta própria","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"O app continua enviando um datagrama a cada 20 ms. Cada um é independente, com o próprio cabeçalho e sem ligação com os outros. O UDP não os numera, e nada volta para confirmar que chegaram.",Rate:"Ritmo","1 datagram / 20 ms":"1 datagrama / 20 ms",Numbering:"Numeração","None in UDP itself":"Nenhuma no próprio UDP",Confirmation:"Confirmação","None (no ACKs)":"Nenhuma (sem ACKs)","voice frames 2–5":"quadros de voz 2–5","each with its own 8-byte header":"cada um com seu cabeçalho de 8 bytes","Lost on the Way":"Perdido no caminho","Nobody resends it":"Ninguém o reenvia","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"O quadro 7 se perde em algum ponto da internet. O servidor de mídia nunca o pede, e o UDP nunca avisa o notebook: não há confirmações cuja falta se note. Os datagramas seguintes chegam normalmente.",Lost:"Perdido","Voice frame 7":"Quadro de voz 7","Never (no ACKs)":"Nunca (sem ACKs)",Missing:"Faltando","20 ms of audio":"20 ms de áudio","voice frames 6–8":"quadros de voz 6–8","frame 7 is lost":"o quadro 7 se perde","Replies Come Back":"As respostas voltam","The other voice comes back":"A outra voz volta","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"A voz da outra pessoa chega do mesmo jeito, em datagramas separados enviados à porta 50000. Eles conseguem entrar porque seu roteador lembrou a porta de saída quando traduziu seu endereço (NAT).",Direction:"Sentido","Independent of ours":"Independente do nosso","Through NAT":"Pelo NAT","Router remembers the port":"O roteador lembra a porta","the other person’s voice":"a voz da outra pessoa","sent to port 50000":"enviada à porta 50000","The App Decides":"O app decide","Reliability is up to the app":"A confiabilidade fica a cargo do app","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"O app de chamadas numera os próprios quadros (o RTP faz isso), então percebe que o quadro 7 falta e disfarça a lacuna de 20 ms em vez de esperar. Esperar um reenvio atrasaria a chamada inteira.","App’s job (e.g. RTP)":"Tarefa do app (ex.: RTP)",Loss:"Perda","Hidden by the app":"Escondida pelo app","Also on UDP":"Também sobre UDP","DNS, games, QUIC":"DNS, jogos, QUIC","Version etc.":"Versão etc.","2, no padding, no extension, no CSRCs":"2, sem preenchimento, sem extensão, sem CSRCs","Marker, payload type":"Marcador, tipo de carga útil","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, combinado ao estabelecer a chamada)","Counts up by one per packet, so the app can spot a missing or late one.":"Aumenta um a cada pacote, para o app notar um que falte ou atrase.",Timestamp:"Carimbo de tempo","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Relógio de áudio a 48,000 por segundo: +960 a cada quadro de 20 ms.","Identifies this audio stream.":"Identifica este fluxo de áudio.",Audio:"Áudio","80 bytes of Opus audio (20 ms)":"80 bytes de áudio Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, combinado ao estabelecer a chamada)","Addressing & Routing":"Endereçamento e roteamento","Outgoing packet":"Pacote de saída",Reply:"Resposta","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"O IP dá um endereço a cada dispositivo e leva os pacotes de rede em rede. Cada roteador olha só o endereço de destino para escolher o próximo salto. O IP é de melhor esforço: não promete entrega nem ordem. O TCP acrescenta isso por cima.","Network (Layer 3)":"Rede (camada 3)",Address:"Endereço","Lowered by 1 at each router":"Diminui 1 em cada roteador",Delivery:"Entrega","Best effort":"Melhor esforço","There and back":"Ida e volta","Twelve routers each way":"Doze roteadores em cada sentido","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"O notebook enviou o pacote ao seu roteador, que colocou o próprio endereço público. Doze roteadores ao todo o repassaram só pelo endereço de destino, e a resposta voltou pelo mesmo caminho. Pressione REPETIR para ver de novo.",Routers:"Roteadores","12 each way (1 home + 11)":"12 por sentido (1 doméstico + 11)","TTL at server":"TTL no servidor","116 (sent with 128)":"116 (enviado com 128)","Rewritten by NAT":"Reescrito pelo NAT","Source out, destination back":"Origem na ida, destino na volta","IPv4 (IPv6 works alike)":"IPv4 (o IPv6 funciona igual)","Local or Not?":"Local ou não?","Compare the address with the subnet":"Compara o endereço com a sub-rede","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"O notebook é 192.168.1.10 com máscara /24, então a rede dele vai de 192.168.1.0 a 192.168.1.255. O servidor, 203.0.113.10, está fora dessa faixa, então o pacote precisa ir para o gateway padrão: o roteador de casa.",Laptop:"Notebook","Local range":"Faixa local",Gateway:"Gateway","Find the Router":"Encontrar o roteador","ARP turns an IP into a MAC":"O ARP transforma um IP em um MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"Na rede local, os quadros são entregues por endereço MAC. Se o MAC do roteador não está no cache ARP do notebook, ele pergunta a todos “quem tem 192.168.1.1?” e o roteador responde com seu endereço MAC.",Asks:"Pergunta","Who has 192.168.1.1?":"Quem tem 192.168.1.1?","Sent to":"Enviado para","Everyone (broadcast)":"Todos (broadcast)",Learns:"Aprende","Router’s MAC address":"O endereço MAC do roteador","who has 192.168.1.1?":"quem tem 192.168.1.1?","tell 192.168.1.10":"avise 192.168.1.10","Send the Packet":"Enviar o pacote","Addresses, TTL and protocol":"Endereços, TTL e protocolo","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"O cabeçalho IP leva os endereços de origem e destino, um TTL e o protocolo que vai dentro. Aqui ele contém um SYN do TCP para a porta 443. O Windows começa o TTL em 128 (Linux e macOS usam 64).","From → to":"De → para","TTL 128 · protocol TCP":"TTL 128 · protocolo TCP","NAT, Then Hop by Hop":"NAT, depois salto a salto","The router rewrites and forwards":"O roteador reescreve e encaminha","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"O roteador troca a origem privada pelo seu endereço público 198.51.100.7 (e aqui a porta 52344 pela 40112), anota o mapeamento e diminui o TTL para 127. Depois, 11 roteadores na internet escolhem cada um o próximo salto pelo destino e diminuem o TTL de novo.","New source":"Nova origem","Leaves home":"Sai de casa","At the server":"No servidor","TTL 116 (11 more hops)":"TTL 116 (mais 11 saltos)","TTL 127 · after NAT":"TTL 127 · depois do NAT","The Reply Comes Back":"A resposta volta","NAT translates it for the laptop":"O NAT a traduz para o notebook","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"O servidor responde ao endereço que viu, 198.51.100.7:40112. O roteador procura isso na tabela NAT, reescreve o destino de volta para 192.168.1.10:52344 e repassa. A resposta saiu com TTL 64 e chega com 52.","Delivered to":"Entregue para","TTL 52 · after NAT":"TTL 52 · depois do NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (depois do NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (depois do NAT)","ARP request · 28 bytes":"Requisição ARP · 28 bytes","Broadcast: every device on the network receives it.":"Broadcast: todos os dispositivos da rede o recebem.","The sender’s network card.":"A placa de rede do remetente.","Hardware type":"Tipo de hardware","Protocol type":"Tipo de protocolo","Address sizes":"Tamanhos de endereço",Operation:"Operação","1 (request: who has …?)":"1 (requisição: quem tem …?)","Sender MAC":"MAC do remetente","Sender IP":"IP do remetente","Target MAC":"MAC de destino","All zeros: this is what the request wants to find out.":"Tudo zero: é isso que a requisição quer descobrir.","Target IP":"IP de destino","ARP reply · 28 bytes":"Resposta ARP · 28 bytes","Straight back to the device that asked.":"Direto de volta para o dispositivo que perguntou.","2 (reply: … is at …)":"2 (resposta: … está em …)","Seen as it leaves the router’s internet side":"Visto ao sair pelo lado de internet do roteador","The internet provider’s router, the next hop.":"O roteador do provedor de internet, o próximo salto.","The router’s internet-facing port.":"A porta do roteador voltada para a internet.","As sent: this system starts at 64.":"Como enviado: este sistema começa em 64.","The router’s NAT swapped in its own port for the laptop’s.":"O NAT do roteador trocou a porta do notebook pela sua.","The sender’s next router; each hop puts the packet in a new frame.":"O próximo roteador do remetente; a cada salto o pacote vai num quadro novo.","Name Resolution":"Resolução de nomes",Query:"Consulta",Referral:"Referência","DNSSEC not requested here":"DNSSEC não é pedido aqui","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"O DNS transforma nomes como www.example.com nos endereços IP que os computadores usam para se encontrar. Nenhum servidor conhece todos os nomes: o sistema é uma hierarquia de servidores, e as respostas ficam em cache pelo caminho, então a maioria das consultas nunca precisa ir longe.","53, UDP (TCP if large)":"53, UDP (TCP se for grande)",Turns:"Transforma","Names into IP addresses":"Nomes em endereços IP",Hierarchy:"Hierarquia","Root → TLD → authoritative":"Raiz → TLD → autoritativo",Caching:"Cache","For each record’s TTL":"Pelo TTL de cada registro","Name resolved":"Nome resolvido","And remembered for an hour":"E lembrado por uma hora","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Partindo de um cache vazio, o resolvedor foi da raiz ao .com e ao próprio servidor de example.com, e então respondeu ao notebook. Até o TTL acabar, a próxima consulta deste nome é respondida direto de um cache. Pressione REPETIR para ver de novo.",Queries:"Consultas","4 (laptop 1, resolver 3)":"4 (notebook 1, resolvedor 3)","Cached for":"Em cache por","Ask the Resolver":"Perguntar ao resolvedor","The laptop hands the question off":"O notebook repassa a pergunta","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"O navegador precisa do endereço IP de www.example.com e nem ele nem o Windows o têm em cache. O notebook envia uma única pergunta ao resolvedor recursivo que recebeu, 8.8.8.8, e pede que ele faça toda a consulta (recursão desejada).","www.example.com, type A":"www.example.com, tipo A",Asked:"Perguntado a","8.8.8.8 (recursive)":"8.8.8.8 (recursivo)","RD (recursion desired)":"RD (recursão desejada)","flags: RD":"flags: RD","Points the way to .com":"Indica o caminho para .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"O cache do resolvedor está vazio (ele acabou de iniciar), então começa pelo topo. Um servidor raiz não sabe o endereço, mas sabe quais servidores cuidam de .com e responde com uma referência. Muitos resolvedores lhe enviam só “com”, não o nome completo.","Root servers":"Servidores raiz","13 names, 1,000+ anycast sites":"13 nomes, mais de 1,000 locais anycast","Referral (13 .com servers)":"Referência (13 servidores .com)","no answer: ask .com":"sem resposta: pergunte ao .com","Points the way to example.com":"Indica o caminho para example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"O resolvedor pergunta a um dos servidores .com. Eles também não guardam endereços de todos os sites, mas sabem quais servidores de nomes cada domínio .com usa, então esta resposta é outra referência, com os endereços desses servidores (glue) anexados.",Knows:"Conhece","Name servers of .com domains":"Os servidores de nomes dos domínios .com","Referral + glue addresses":"Referência + endereços glue","no answer: ask example.com":"sem resposta: pergunte ao example.com","Gives the actual answer":"Dá a resposta de verdade","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Por fim o resolvedor pergunta ao próprio servidor de nomes de example.com, que guarda os registros do domínio. Ele responde com o registro A e marca a resposta como autoritativa. O dono do domínio define por quanto tempo ela pode ficar em cache: aqui, 3600 segundos.","AA (authoritative), TTL 3600":"AA (autoritativa), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · flag AA","Answer & Cache":"Resposta e cache","The laptop gets its address":"O notebook recebe seu endereço","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"O resolvedor devolve a resposta ao notebook e guarda uma cópia. Durante a próxima hora ele pode responder este nome na hora, e é por isso que a consulta na lição de HTTP levou só 24 ms. O notebook também a guarda em cache.","RD, RA (recursion available)":"RD, RA (recursão disponível)","Cached by":"Em cache em","Resolver and laptop":"Resolvedor e notebook","flags: RD RA":"flags: RD RA","Referral: com. NS ×13 (with glue)":"Referência: com. NS ×13 (com glue)","Referral: example.com. NS ×2 (with glue)":"Referência: example.com. NS ×2 (com glue)","Response A 203.0.113.10 (authoritative)":"Resposta A 203.0.113.10 (autoritativa)","As sent: this system starts at 128.":"Como enviado: este sistema começa em 128.","0x0000: query":"0x0000: consulta","UDP size 1232, DNSSEC OK = 0":"Tamanho UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Diz o tamanho máximo de uma resposta UDP. As assinaturas DNSSEC não são pedidas aqui, para manter a lição curta; um resolvedor que valida, como o 8.8.8.8, as pede.","0x8000: response":"0x8000: resposta",Authority:"Autoridade",Additional:"Adicional","0x8400: response, AA (authoritative)":"0x8400: resposta, AA (autoritativa)","Getting an Address":"Obtendo um endereço","From the laptop":"Do notebook","From the DHCP server":"Do servidor DHCP","Dynamic Host Configuration Protocol":"Protocolo de configuração dinâmica de host","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"O DHCP entrega a um dispositivo tudo o que ele precisa para usar uma rede: um endereço IP, a máscara de sub-rede, o roteador pelo qual enviar o tráfego e os servidores DNS a consultar. Os endereços são concedidos por um tempo definido e renovados enquanto o dispositivo continua na rede.","UDP 67 (server), 68 (client)":"UDP 67 (servidor), 68 (cliente)","Hands out":"Entrega","IP, mask, gateway, DNS":"IP, máscara, gateway, DNS",Exchange:"Troca",Lease:"Concessão","Renewed at half its time":"Renovada na metade do prazo","On the network":"Na rede","Leased, and kept up to date":"Com concessão, e sempre em dia","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Quatro mensagens levaram o notebook de nenhum endereço a uma configuração funcionando, e na metade da concessão de 24 horas ele a renovou com um pedido direto ao roteador. Pressione REPETIR para ver de novo.",Messages:"Mensagens","4 to join, 2 per renewal":"4 para entrar, 2 por renovação","24 h, renewed at 12 h":"24 h, renovada às 12 h","No Address Yet":"Ainda sem endereço","The laptop joins the network":"O notebook entra na rede","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"O notebook acabou de se conectar. Ele tem um endereço MAC de fábrica, mas nenhum endereço IP, nenhum gateway e nenhum servidor DNS, então ainda não consegue falar com nada além da própria rede. Ele os pede com DHCP.","IP address":"Endereço IP","None (uses 0.0.0.0)":"Nenhum (usa 0.0.0.0)","MAC address":"Endereço MAC",Needs:"Precisa de",Discover:"Descoberta","Shout to the whole network":"Gritar para a rede inteira","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Sem endereço próprio, o notebook envia de 0.0.0.0 para o endereço de broadcast 255.255.255.255, então todos os dispositivos da rede local o recebem. Só os servidores DHCP respondem.",From:"De","0.0.0.0, UDP port 68":"0.0.0.0, porta UDP 68","255.255.255.255, port 67":"255.255.255.255, porta 67",Carries:"Leva","MAC, transaction ID":"MAC, ID da transação","any DHCP server out there?":"algum servidor DHCP por aí?",Offer:"Oferta","The router proposes an address":"O roteador propõe um endereço","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"O servidor DHCP do roteador escolhe um endereço livre e o oferece junto com as demais configurações. O notebook ainda não pode usar um endereço IP, então a oferta vai direto para o seu endereço MAC (alguns clientes pedem um broadcast).",Offered:"Oferecido","Gateway, DNS":"Gateway, DNS","offer: 192.168.1.10/24":"oferta: 192.168.1.10/24","gateway, DNS, lease 24 h":"gateway, DNS, concessão de 24 h","Accept, out loud":"Aceitar em voz alta","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"O notebook pede o endereço oferecido, nomeando o servidor que escolheu. Ele ainda usa broadcast, assim qualquer outro servidor DHCP que tenha feito uma oferta fica sabendo que não foi escolhido e pode liberar o endereço.",Requests:"Pede","Chosen server":"Servidor escolhido","I’ll take 192.168.1.10":"Fico com 192.168.1.10","from server 192.168.1.1":"do servidor 192.168.1.1",Acknowledge:"Confirmação","The address is the laptop’s":"O endereço é do notebook","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"O servidor confirma, e o notebook configura seu endereço, máscara, gateway e servidor DNS. Muitos sistemas primeiro verificam com ARP que nenhum outro dispositivo já está usando o endereço.","DNS server":"Servidor DNS","192.168.1.10 is yours":"192.168.1.10 é seu","for 24 hours":"por 24 horas",Renew:"Renovação","Halfway through the lease":"Na metade da concessão","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Doze horas depois, metade da concessão já passou. Agora o notebook tem endereço, então pede direto ao roteador para estender a concessão, e o roteador a renova para 24 horas. Se o roteador não respondesse, ele usaria broadcast aos 87.5%.",When:"Quando","50% of lease (T1 = 12 h)":"50% da concessão (T1 = 12 h)","The router (unicast)":"O roteador (unicast)","If unanswered":"Sem resposta","Broadcast at 87.5% (T2)":"Broadcast aos 87.5% (T2)","renew 192.168.1.10":"renovar 192.168.1.10","sent straight to 192.168.1.1":"enviado direto para 192.168.1.1","lease renewed":"concessão renovada","another 24 hours":"mais 24 horas",Message:"Mensagem","1 (request, from a client)":"1 (requisição, de um cliente)",Hardware:"Hardware","Ethernet, 6-byte addresses":"Ethernet, endereços de 6 bytes",Hops:"Saltos","Chosen by the client; every reply repeats it.":"Escolhido pelo cliente; toda resposta o repete.",Seconds:"Segundos","0x0000 (unicast replies are fine)":"0x0000 (respostas unicast servem)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Flag de broadcast desligada: o servidor pode enviar direto para o endereço MAC do cliente.","Client address":"Endereço do cliente","Filled in only when the client already has an address (renewing).":"Preenchido só quando o cliente já tem endereço (renovação).","Your address":"Seu endereço","The address the server is giving out.":"O endereço que o servidor está entregando.","Next server":"Próximo servidor","Relay agent":"Agente de retransmissão","Client MAC":"MAC do cliente","Server name, boot file":"Nome do servidor, arquivo de boot",empty:"vazio","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Marca as opções seguintes como DHCP.","Message type: 1 (Discover)":"Tipo de mensagem: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Identificador do cliente: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Nome do host: alice-laptop","Vendor class: MSFT 5.0":"Classe do fabricante: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Parâmetros pedidos: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (resposta, de um servidor)","Message type: 2 (Offer)":"Tipo de mensagem: 2 (Offer)","Server identifier: 192.168.1.1":"Identificador do servidor: 192.168.1.1","Lease time: 86,400 s (24 h)":"Tempo de concessão: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"Tempo de renovação (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"Tempo de nova vinculação (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"Máscara de sub-rede: 255.255.255.0","Broadcast address: 192.168.1.255":"Endereço de broadcast: 192.168.1.255","DNS server: 8.8.8.8":"Servidor DNS: 8.8.8.8","Message type: 3 (Request)":"Tipo de mensagem: 3 (Request)","Requested address: 192.168.1.10":"Endereço pedido: 192.168.1.10","Client FQDN: alice-laptop":"FQDN do cliente: alice-laptop","Message type: 5 (ACK)":"Tipo de mensagem: 5 (ACK)","Network Diagnostics":"Diagnóstico de rede","Ping / probe":"Ping / sonda","Echo reply":"Resposta de eco","Error report":"Relatório de erro","Internet Control Message Protocol":"Protocolo de mensagens de controle da internet","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"O ICMP é o jeito de a rede dar retorno: um roteador avisa que o tempo de um pacote acabou, um servidor avisa que nada escuta numa porta. Ferramentas como ping e traceroute são feitas dessas mensagens. Ele viaja dentro do IP, mas não leva dados de aplicação.","Carried in":"Viaja em","IP (protocol 1)":"IP (protocolo 1)","A type and a code":"Um tipo e um código",Tools:"Ferramentas",Often:"Muitas vezes","Filtered by firewalls":"Filtrado por firewalls","The network answered":"A rede respondeu","Replies, expiries and errors":"Respostas, expirações e erros","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Uma requisição de eco mediu a ida e volta, pacotes com TTL pequeno fizeram cada roteador do caminho se identificar, e uma porta fechada foi informada na hora. Pressione REPETIR para ver de novo.","Round trip":"Ida e volta",Path:"Caminho","12 routers, server at hop 13":"12 roteadores, servidor no salto 13","Types used":"Tipos usados","8, 0, 11 and 3":"8, 0, 11 e 3","Reply TTL":"TTL da resposta",Ping:"Ping","Echo request":"Requisição de eco","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"“ping -n 1 203.0.113.10” envia uma requisição de eco ICMP (o ping simples envia quatro, uma por segundo): tipo 8, código 0, com um identificador, um número de sequência e 32 bytes de preenchimento. O sistema do servidor responde sozinho, sem precisar de aplicativo.","Type, code":"Tipo, código","8, 0 (echo request)":"8, 0 (requisição de eco)","type 8 · seq 1":"tipo 8 · seq 1","32 bytes of data":"32 bytes de dados","Echo Reply":"Resposta de eco","Round-trip time":"Tempo de ida e volta","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"O servidor devolve uma resposta de eco, tipo 0, com o mesmo identificador, número de sequência e dados. O ping mostra quanto tempo levou e com que TTL a resposta chegou: “bytes=32 tempo=34ms TTL=52”.","0, 0 (echo reply)":"0, 0 (resposta de eco)","TTL on arrival":"TTL na chegada","type 0 · seq 1":"tipo 0 · seq 1","same 32 bytes back":"os mesmos 32 bytes de volta","The first router answers":"O primeiro roteador responde","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"“ping -n 1 -i 1” envia a mesma requisição com TTL 1. O roteador de casa o diminui para 0, então precisa descartar o pacote, e devolve uma mensagem de tempo excedido (Time Exceeded) do seu próprio endereço: “Resposta de 192.168.1.1: TTL expirou durante trânsito.”","Sent with":"Enviado com","Dropped by":"Descartado por","11, 0 (time exceeded)":"11, 0 (tempo excedido)","echo request":"requisição de eco","expires at the first router":"expira no primeiro roteador","type 11 · from 192.168.1.1":"tipo 11 · de 192.168.1.1","quotes the dropped header":"cita o cabeçalho descartado","The next router answers":"O roteador seguinte responde","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"Com “-i 2”, o roteador de casa diminui o TTL para 1 e repassa. O primeiro roteador do provedor de internet o diminui para 0 e avisa a partir de 198.51.100.1. O roteador de casa traduz o aviso de volta para o notebook como qualquer resposta.","ISP router 198.51.100.1":"Roteador do provedor 198.51.100.1","expires at the second router":"expira no segundo roteador","type 11 · from 198.51.100.1":"tipo 11 · de 198.51.100.1","That’s Traceroute":"Isso é o traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … até chegar","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"O tracert automatiza isso: aumenta o TTL em um a cada vez, envia três sondas por salto e lista quem responde. Os saltos 3 a 12 funcionam do mesmo jeito, e com TTL 13 a requisição enfim chega ao servidor, que responde normalmente.","12 routers, then the server":"12 roteadores, depois o servidor","Per hop":"Por salto","3 probes":"3 sondas","On Linux":"No Linux","traceroute sends UDP":"o traceroute envia UDP","enough hops to arrive":"saltos suficientes para chegar","the server itself answers":"o próprio servidor responde","end of the route":"fim da rota",Unreachable:"Inalcançável","Nothing listening on that port":"Nada escuta nessa porta","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Um app envia um datagrama UDP para a porta 9999, onde nada está escutando. O servidor não consegue entregá-lo, então responde com Destino inalcançável, código 3 (porta inalcançável), citando o começo do datagrama. Muitos firewalls descartam esses pacotes em silêncio.","3, 3 (port unreachable)":"3, 3 (porta inalcançável)","Other codes":"Outros códigos","0 net, 1 host, 4 too big":"0 rede, 1 host, 4 grande demais",Firewalls:"Firewalls","Often silent instead":"Muitas vezes, silêncio","to port 9999":"para a porta 9999","nothing listening there":"nada escuta ali","type 3 · code 3":"tipo 3 · código 3","port unreachable":"porta inalcançável","ICMP · Echo request":"ICMP · Requisição de eco",Code:"Código","Covers the whole ICMP message.":"Cobre a mensagem ICMP inteira.",Identifier:"Identificador","Matches replies to this ping program.":"Associa as respostas a este programa de ping.","Windows counts up across every ping it sends.":"O Windows vai contando entre todos os pings que envia.","Windows ping’s filler: the alphabet, a to w, then again.":"O preenchimento do ping do Windows: o alfabeto, de a a w, e de novo.","ICMP · Echo reply":"ICMP · Resposta de eco","Sent back exactly as it came.":"Devolvido exatamente como chegou.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Tempo excedido (TTL chegou a 0)","Time exceeded (TTL reached 0)":"Tempo excedido (TTL chegou a 0)",Unused:"Não usado","Original packet":"Pacote original","Its source, destination":"Sua origem e seu destino","its IP header and first 8 bytes (28 bytes)":"seu cabeçalho IP e os primeiros 8 bytes (28 bytes)","App data":"Dados do app","What the app sent; nothing on the server is listening for it.":"O que o app enviou; nada no servidor está esperando por isso.","ICMP · Destination unreachable (port unreachable)":"ICMP · Destino inalcançável (porta inalcançável)","Destination unreachable (port unreachable)":"Destino inalcançável (porta inalcançável)","Sending Email":"Enviando e-mail","SMTP command":"Comando SMTP","SMTP reply":"Resposta SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"O SMTP transporta e-mails: do seu app de e-mail para o servidor do seu provedor, e desse servidor para o do destinatário. É uma conversa de comandos curtos em texto, cada um respondido com um código de três dígitos. Ler e-mails é outra tarefa, feita com IMAP ou POP3.","465/587 submit, 25 relay":"465/587 envio, 25 retransmissão","TCP, usually with TLS":"TCP, normalmente com TLS",Commands:"Comandos",Replies:"Respostas","2xx ok, 3xx go on, 4/5xx error":"2xx ok, 3xx continue, 4/5xx erro","Mail delivered":"E-mail entregue","Two hops, one message":"Dois saltos, uma mensagem","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"O app da Alice entregou a mensagem ao provedor dela por uma conexão criptografada e autenticada. O provedor encontrou o servidor de e-mail do Bob no DNS e a retransmitiu para lá, passando esse enlace para TLS. Agora ela espera na caixa de entrada do Bob até ele lê-la com IMAP ou POP3.","Laptop → provider → Bob’s":"Notebook → provedor → Bob",Submission:"Envio","Port 465, TLS, login":"Porta 465, TLS, login",Relay:"Retransmissão","Port 25, STARTTLS":"Porta 25, STARTTLS","Checks at Bob’s":"Verificações no servidor do Bob","Connect Securely":"Conectar com segurança","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Alice clica em Enviar. O app de e-mail dela se conecta ao servidor de envio do provedor, smtp.example.com, na porta 465. Nessa porta o TLS começa imediatamente, então toda a conversa SMTP, inclusive a senha dela, é criptografada.","TLS from the start":"TLS desde o início","SMTP inside TLS":"SMTP dentro do TLS","Greeting & Login":"Saudação e login","EHLO, then AUTH":"EHLO, depois AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"O servidor cumprimenta com o código 220. O app diz EHLO e o servidor lista o que suporta, incluindo AUTH. O app faz login com AUTH PLAIN (usuário e senha, em base64) e recebe 235: autenticado.",Greeting:"Saudação",Capabilities:"Recursos","Login result":"Resultado do login","user and password, base64":"usuário e senha, em base64","Send the Message":"Enviar a mensagem","Envelope, then content":"Envelope, depois conteúdo","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM e RCPT TO são o envelope: remetente e destinatário. O PIPELINING deixa os três comandos irem num só pacote. Depois do 354 vem a mensagem, terminada por uma linha só com um ponto.",Envelope:"Envelope","Content ends":"Fim do conteúdo","A line with only “.”":"Uma linha só com “.”",Result:"Resultado","… message …":"… mensagem …","Find Bob’s Server":"Encontrar o servidor do Bob","An MX lookup in DNS":"Uma consulta MX no DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"O provedor da Alice agora precisa entregar em example.org. Ele pede ao DNS o registro MX desse domínio, que indica o servidor que aceita os e-mails dele, e depois consulta o endereço desse servidor.","MX record":"Registro MX","Asked by":"Consultado por","Alice’s provider":"Provedor da Alice","Server to Server":"De servidor para servidor","Port 25, upgraded with STARTTLS":"Porta 25, atualizada com STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"O provedor se conecta a mx.example.org na porta 25. Essa conversa começa em texto puro: a saudação e a resposta ao EHLO anunciam STARTTLS, o provedor o pede, recebe 220 e os dois lados passam para TLS.","Starts as":"Começa como","Plain text":"Texto puro",Upgrade:"Atualização",Deliver:"Entregar","The same transaction again":"A mesma transação de novo","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Com o TLS ativo, o provedor repete o EHLO, depois o envelope e a mensagem, agora com uma assinatura DKIM e um cabeçalho Received acrescentados. O servidor do Bob verifica SPF, DKIM e DMARC e a aceita.","Login needed":"Precisa de login","No (server to server)":"Não (de servidor para servidor)","1,316 bytes (signed)":"1,316 bytes (assinada)","Server Hello + encrypted handshake, 2 segments":"Server Hello + handshake criptografado, 2 segmentos","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 recursos (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (credenciais)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (em pipeline)","Message (316 bytes), then “.”":"Mensagem (316 bytes), depois “.”","250 capabilities (PIPELINING, STARTTLS …)":"250 recursos (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 recursos (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Mensagem (1,316 bytes), depois “.”","What this client supports. Its exact contents vary from client to client; this is an example.":"O que este cliente suporta. O conteúdo exato varia de cliente para cliente; isto é um exemplo.","up to 512 bytes":"até 512 bytes","The server’s choices and its key share.":"As escolhas do servidor e sua parte da chave.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (a cadeia), Certificate Verify (a assinatura), Finished","Alice’s message (316 bytes), then a line holding only “.”":"A mensagem da Alice (316 bytes), depois uma linha só com “.”","example.org, type MX, class IN":"example.org, tipo MX, classe IN","mx.example.org, type A, class IN":"mx.example.org, tipo A, classe IN",Timestamps:"Carimbos de tempo","Used to measure round trips; both sides offered them.":"Usados para medir idas e voltas; os dois lados os ofereceram.","The signed message (1,316 bytes), then a line holding only “.”":"A mensagem assinada (1,316 bytes), depois uma linha só com “.”","Downloading Email":"Baixando e-mails","POP3 command":"Comando POP3","POP3 reply":"Resposta POP3","Post Office Protocol, version 3":"Protocolo de agência de correio, versão 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"O POP3 permite a um app de e-mail baixar mensagens de uma caixa de correio num servidor. Foi pensado para um só dispositivo, que busca os e-mails e depois os apaga do servidor. Os comandos são palavras curtas, e toda resposta começa com +OK ou -ERR.",Model:"Modelo","Download, then delete":"Baixar, depois apagar","Mail downloaded":"E-mail baixado","And gone from the server":"E removido do servidor","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"O app do Bob fez login, viu duas mensagens, baixou a primeira e a apagou, o que o servidor executou no QUIT. Essa mensagem agora existe só neste notebook, e é por isso que o POP3 combina com um dispositivo e o IMAP com vários.","2 waiting, 1 downloaded":"2 esperando, 1 baixada",Deleted:"Apagada","At QUIT (UPDATE state)":"No QUIT (estado UPDATE)","Best for":"Ideal para","A single device":"Um só dispositivo","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"O app de e-mail do Bob se conecta a pop.example.org na porta 995, onde o TLS começa na hora. Dentro dele, o servidor cumprimenta com +OK. (Na porta 110 a sessão começa em texto puro e é atualizada com o comando STLS.)","USER, then PASS":"USER, depois PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"O app envia o nome de usuário com USER e a senha com PASS. Cada comando recebe seu próprio +OK. Como a sessão está dentro do TLS, a senha não pode ser lida no caminho.","Protected by":"Protegido por","Check the Mailbox":"Verificar a caixa de correio","STAT and LIST":"STAT e LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"O STAT devolve o número de mensagens e o tamanho total: 2 mensagens, 5120 bytes. O LIST dá o número e o tamanho de cada mensagem e termina com uma linha só com um ponto.","Message 1":"Mensagem 1","Message 2":"Mensagem 2",Download:"Baixar","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 pede a primeira mensagem. O servidor responde +OK com o tamanho, depois a mensagem e um ponto final: 1904 bytes mais a linha de resposta, dois segmentos TCP.",Command:"Comando","Delete & Quit":"Apagar e sair","Deleted only at QUIT":"Apagada só no QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 só marca a mensagem. O servidor a remove quando o app diz QUIT: se a conexão caísse antes disso, nada seria apagado. Muitos apps oferecem “deixar uma cópia no servidor”, que pula o DELE.","Marks message 1":"Marca a mensagem 1",Removed:"Removida",Option:"Opção","Leave a copy on server":"Deixar uma cópia no servidor","PASS (password)":"PASS (senha)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, mensagem, “.” (2 segmentos)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, a mensagem de 1,904 bytes, depois uma linha só com “.”","Mail That Stays in Sync":"E-mail que fica sincronizado","IMAP command":"Comando IMAP","IMAP response":"Resposta IMAP","Internet Message Access Protocol":"Protocolo de acesso a mensagens da internet","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"O IMAP permite que apps de e-mail trabalhem com uma caixa de correio que fica no servidor. Pastas, marcas de lido e sinalizado e exclusões ficam guardadas lá, então um celular, um notebook e o webmail veem a mesma caixa. O servidor também pode avisar um app sobre e-mails novos assim que chegam.","Mail stays on the server":"O e-mail fica no servidor",Syncs:"Sincroniza","Folders and flags":"Pastas e sinalizadores","Mailbox in sync":"Caixa de correio sincronizada","Read once, read everywhere":"Lido uma vez, lido em todo lugar","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"O app do Bob abriu a caixa de entrada e leu uma mensagem, o que a marcou como \\Seen no servidor para todos os dispositivos dele, e então esperou com IDLE até o servidor anunciar um e-mail novo. Nada foi apagado: o servidor ainda guarda tudo.","2, then 3 (new mail)":"2, depois 3 (e-mail novo)","Read mark":"Marca de lido","\\Seen, stored on server":"\\Seen, guardado no servidor","New mail":"E-mail novo","Pushed during IDLE":"Enviado durante o IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"O app do Bob se conecta a imap.example.org na porta 993, onde o TLS começa na hora. O servidor cumprimenta com uma linha “* OK” sem tag que também lista seus recursos, como IDLE.","Commands carry tags":"Os comandos levam tags","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Todo comando começa com uma tag que o app escolhe, como a1, e o servidor termina a resposta com a mesma tag. Assim vários comandos podem estar em andamento e cada resposta é associada ao seu. Linhas que começam com * são dados sem tag.",Tags:"Tags","Match replies to commands":"Associam respostas a comandos","Open the Inbox":"Abrir a caixa de entrada","SELECT a folder":"SELECT numa pasta","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX abre a pasta. O servidor informa o número de mensagens, os sinalizadores que suporta e a primeira mensagem não lida, e depois confirma que a pasta está aberta para leitura e escrita.","First unread":"Primeira não lida",Access:"Acesso","Read a Message":"Ler uma mensagem","FETCH, and the \\Seen flag":"FETCH e o sinalizador \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] baixa a mensagem 2 (três segmentos TCP). Isso ativa o sinalizador \\Seen dela no servidor, então ela aparece como lida no celular do Bob também, e a mensagem continua lá.","Flag set":"Sinalizador ativado","\\Seen (on the server)":"\\Seen (no servidor)","Wait for New Mail":"Esperar por e-mail novo","IDLE: the server pushes":"IDLE: o servidor avisa","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"O IDLE diz ao servidor “me avise quando algo mudar”. Cerca de 42 segundos depois chega a mensagem da Alice e o servidor envia “* 3 EXISTS” na hora. O app encerra o IDLE com DONE e pode buscar o e-mail novo.","Server says":"O servidor diz","* 3 EXISTS (new mail)":"* 3 EXISTS (e-mail novo)","Ended by":"Encerrado com","a1 LOGIN (user and password)":"a1 LOGIN (usuário e senha)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, a mensagem de 3,216 bytes, depois a3 OK FETCH completed","Transferring Files":"Transferindo arquivos","FTP command":"Comando FTP","FTP reply":"Resposta FTP","File data":"Dados do arquivo","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"O FTP transfere arquivos entre um cliente e um servidor. Ele é incomum por usar duas conexões TCP: uma para comandos e respostas, e uma nova para cada arquivo ou listagem. É do começo dos anos 1970 e envia tudo, inclusive senhas, em texto puro.","21 control, data varies":"21 controle, dados variam",Connections:"Conexões","Control + one per transfer":"Controle + uma por transferência",Encryption:"Criptografia","None (plain text)":"Nenhuma (texto puro)","Safer options":"Opções mais seguras","File downloaded":"Arquivo baixado","Two connections, no encryption":"Duas conexões, nenhuma criptografia","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Os comandos foram pela conexão de controle, o arquivo pela sua própria conexão de dados, e o fechamento dessa conexão marcou o fim do arquivo. Qualquer um no caminho poderia ter lido a senha e o arquivo, e é por isso que hoje se usa SFTP ou FTPS.","2 (control + data)":"2 (controle + dados)",File:"Arquivo","4,000 bytes, 3 segments":"4,000 bytes, 3 segmentos",Password:"Senha","Sent in plain text":"Enviada em texto puro","Use instead":"Use no lugar","Control Connection":"Conexão de controle","Port 21, plain text":"Porta 21, texto puro","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"O app de FTP abre uma conexão TCP com ftp.example.com na porta 21. Essa conexão de controle leva os comandos e as respostas da sessão inteira. O servidor cumprimenta com 220. Como no SMTP, toda resposta começa com um código de três dígitos.","USER and PASS, readable by anyone":"USER e PASS, legíveis por qualquer um","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"O app envia USER, o servidor pede a senha com 331, e PASS a envia. Nada é criptografado, então o nome de usuário e a senha atravessam todas as redes do caminho como texto legível.","Visible to":"Visível para","Anyone on the path":"Qualquer um no caminho","Passive Mode":"Modo passivo","The server names a data port":"O servidor indica uma porta de dados","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I pede uma cópia binária byte a byte. PASV pede ao servidor que abra uma porta para a conexão de dados. A resposta codifica o endereço e a porta em seis números: 195 × 256 + 149 = porta 50069. O notebook conecta para fora, o que funciona através do NAT.","Data port":"Porta de dados","Active mode":"Modo ativo","Server dials in: NAT blocks":"O servidor liga de volta: o NAT bloqueia","Data Connection":"Conexão de dados","A second TCP connection":"Uma segunda conexão TCP","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"O app abre uma segunda conexão TCP, para a porta 50069, e pede o arquivo na conexão de controle com RETR. O servidor responde 150 ali e começa a enviar o arquivo pela nova conexão.","Data to":"Dados para","The File Arrives":"O arquivo chega","Closing the connection ends it":"Fechar a conexão marca o fim","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"Os 4,000 bytes chegam em 3 segmentos TCP. O FTP não manda nenhum indicador de tamanho nos próprios dados: o servidor fecha a conexão de dados para marcar o fim do arquivo. Quando o notebook confirma tudo, o servidor confirma com 226 na conexão de controle.","End of file":"Fim do arquivo","Data connection closed":"Conexão de dados fechada","4,000 bytes, readable by anyone":"4,000 bytes, legíveis por qualquer um","end of file:":"fim do arquivo:","data connection closed":"conexão de dados fechada",Quit:"Sair","Close the control connection":"Fechar a conexão de controle","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"O QUIT encerra a sessão e o servidor se despede com 221. Para qualquer coisa sensível, o SFTP (outro protocolo, que roda sobre SSH) ou o FTPS (FTP dentro do TLS) fazem o mesmo trabalho com criptografia.","Encrypted cousins":"Primos criptografados","FTP data":"Dados FTP","The file itself, unencrypted: anyone on the path could read it.":"O próprio arquivo, sem criptografia: qualquer um no caminho poderia lê-lo.","Secure Remote Login":"Login remoto seguro","Plain setup":"Estabelecimento em claro","From laptop":"Do notebook","From server":"Do servidor","Some packets not shown":"Alguns pacotes não aparecem","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"O SSH dá a você uma conexão criptografada e autenticada com outro computador, para executar comandos nele, copiar arquivos (SFTP, scp) ou transportar outras conexões. O servidor prova quem é com uma chave de host; você prova quem é com um par de chaves ou uma senha.","Server proves":"O servidor prova","Host key (known_hosts)":"Chave de host (known_hosts)","You prove":"Você prova","Key pair or password":"Par de chaves ou senha","Logged in securely":"Login seguro feito","Encrypted from the key exchange on":"Criptografado a partir da troca de chaves","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"Os dois lados combinaram os algoritmos, criaram chaves compartilhadas com uma troca híbrida pós-quântica, e o servidor provou sua identidade com a chave de host. Alice provou a dela assinando com uma chave privada que nunca saiu do notebook e depois digitou um comando, um pacote por tecla.",Login:"Login","Ed25519 key, no password":"Chave Ed25519, sem senha","Say Hello":"Dizer olá","Versions, in plain text":"Versões, em texto puro","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Alice executa “ssh alice@server.example.com”. Depois do handshake TCP na porta 22, cada lado envia uma linha de texto puro com a versão do protocolo SSH (2.0) e o seu software. Todo o resto no SSH é binário.","Agree on Algorithms":"Combinar os algoritmos","KEXINIT lists, first match wins":"Listas KEXINIT, vence a primeira coincidência","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Cada lado envia um KEXINIT listando todos os algoritmos que suporta, em ordem de preferência, para troca de chaves, chaves de host, criptografia, integridade e compressão. Em cada categoria é escolhido o primeiro algoritmo da lista do notebook que o servidor também suporta.","Host key":"Chave de host","server’s algorithm lists":"listas de algoritmos do servidor","in order of preference":"em ordem de preferência","laptop’s algorithm lists":"listas de algoritmos do notebook","Key Exchange":"Troca de chaves","Shared keys, and a host key check":"Chaves compartilhadas e uma verificação da chave de host","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"O notebook envia a sua metade de uma troca híbrida: uma chave Streamlined NTRU Prime, escolhida para resistir a futuros computadores quânticos, mais uma chave X25519. O servidor responde com a sua metade, a sua chave de host e uma assinatura sobre a troca. O NEWKEYS liga a criptografia.",Hybrid:"Híbrida","Matches known_hosts":"Confere com known_hosts","First visit":"Primeira visita","ssh asks you to confirm":"O ssh pede que você confirme","public keys":"chaves públicas","its half, its host key":"sua metade, sua chave de host","and a signature":"e uma assinatura","Log In with a Key":"Login com uma chave","Sign, don’t send a secret":"Assine, não envie um segredo","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"O servidor lista os métodos de login que aceita. O notebook oferece a chave pública da Alice, e o servidor diz que a aceitaria. O notebook então assina esta sessão com a chave privada, que nunca sai do notebook. O servidor confere a assinatura com o authorized_keys.",Methods:"Métodos","Ed25519, private stays here":"Ed25519, a privada fica aqui","Checked with":"Verificado com","alice’s public key":"chave pública da alice","would you accept it?":"você a aceitaria?","yes, that key":"sim, essa chave","is in authorized_keys":"está no authorized_keys","same key, plus a signature":"a mesma chave, mais uma assinatura","made with the private key":"feita com a chave privada","logged in":"login feito","Open a Session":"Abrir uma sessão","Channels inside one connection":"Canais dentro de uma só conexão","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Uma conexão SSH pode levar muitos canais: um shell, transferências de arquivos, portas encaminhadas. O notebook abre um canal de sessão, depois pede um terminal e um shell (não mostrados), e o servidor envia seu texto de boas-vindas e um prompt.",Channel:"Canal",session:"sessão","Then asks for":"Depois pede","A terminal and a shell":"Um terminal e um shell","Also possible":"Também possível","SFTP, port forwarding":"SFTP, encaminhamento de portas","open a channel:":"abrir um canal:","channel open":"canal aberto","Type a Command":"Digitar um comando","Every key is a packet":"Cada tecla é um pacote","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Alice digita pwd. Cada tecla sai na hora em seu próprio pacote criptografado, e o servidor devolve o caractere para ser exibido (o eco). Desde a versão 9.5, o OpenSSH envia as teclas num ritmo de 20 ms e acrescenta pacotes falsos, para que o ritmo de digitação seja mais difícil de deduzir pelo tempo.","Per key":"Por tecla","1 packet, 90 bytes":"1 pacote, 90 bytes",Echo:"Eco","Sent back by the server":"Devolvido pelo servidor",Timing:"Tempo","20 ms beat plus decoys":"Ritmo de 20 ms e pacotes falsos","Enter key":"Tecla Enter","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Client: KEX_ECDH_INIT (chaves públicas sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Server: KEX_ECDH_REPLY (chave de host, sua metade, assinatura)","Encrypted (len=44): service request, ssh-userauth":"Criptografado (len=44): pedido de serviço, ssh-userauth","Encrypted (len=44): service accept":"Criptografado (len=44): serviço aceito","Encrypted (len=68): login with method none":"Criptografado (len=68): login com o método none","Encrypted (len=52): try publickey,password":"Criptografado (len=52): tente publickey,password","Encrypted (len=140): offer public key":"Criptografado (len=140): oferece chave pública","Encrypted (len=100): public key OK":"Criptografado (len=100): chave pública OK","Encrypted (len=308): public key + signature":"Criptografado (len=308): chave pública + assinatura","Encrypted (len=28): login success":"Criptografado (len=28): login bem-sucedido","Encrypted (len=52): channel open: session":"Criptografado (len=52): abrir canal: session","Encrypted (len=44): channel open confirmed":"Criptografado (len=44): abertura do canal confirmada","Encrypted (len=36): keystroke":"Criptografado (len=36): tecla","Encrypted (len=36): echo":"Criptografado (len=36): eco","Encrypted (len=36): keystroke (Enter)":"Criptografado (len=36): tecla (Enter)","Encrypted (len=132): output and a new prompt":"Criptografado (len=132): saída e um novo prompt","Packet length":"Tamanho do pacote","Bytes after this field.":"Bytes depois deste campo.","Padding length":"Tamanho do preenchimento","Random padding brings the packet to a multiple of 8 bytes.":"Um preenchimento aleatório deixa o pacote com um múltiplo de 8 bytes.",Cookie:"Cookie","Host keys":"Chaves de host","Ciphers, out":"Cifras, saída","Ciphers, in":"Cifras, entrada","MACs, out":"MACs, saída","Compression, out":"Compressão, saída","Compression, in":"Compressão, entrada","Languages, out":"Idiomas, saída","Languages, in":"Idiomas, entrada","First packet follows":"Segue o primeiro pacote",Reserved:"Reservado","Public keys":"Chaves públicas","51 bytes: ssh-ed25519 public key":"51 bytes: chave pública ssh-ed25519","Server’s half":"Metade do servidor","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 bytes (texto cifrado sntrup761 1,039 + X25519 32)",Signature:"Assinatura","83 bytes: ssh-ed25519 signature over the exchange":"83 bytes: assinatura ssh-ed25519 sobre a troca","From the next packet on, this side encrypts.":"A partir do próximo pacote, este lado criptografa.","SSH · encrypted packet":"SSH · pacote criptografado","Encrypted packet":"Pacote criptografado","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"Com chacha20-poly1305 até o tamanho é criptografado; uma tag de 16 bytes no fim revela qualquer alteração.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): usuário “alice”, serviço “ssh-connection”, método “none”","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): métodos que podem continuar: “publickey,password”","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): método “publickey”, sem assinatura, a chave pública ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): a mesma chave ssh-ed25519","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): método “publickey-hostbound-v00@openssh.com”, a chave, a chave de host do servidor e uma assinatura","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): “session”, canal 0, janela de 2 MB, pacotes de até 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): o canal 0 está aberto","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), canal 0: 1 byte, “p”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canal 0: 1 byte, “p”, devolvido para ser exibido","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), canal 0: 1 byte, “w”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canal 0: 1 byte, “w”, devolvido para ser exibido","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), canal 0: 1 byte, “d”","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), canal 0: 1 byte, “d”, devolvido para ser exibido","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), canal 0: 1 byte, um retorno de carro (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), canal 0: 94 bytes: uma quebra de linha, os códigos de terminal do shell, “/home/alice” e o prompt colorido","Encryption Explained":"Criptografia explicada","From browser":"Do navegador","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"O TLS coloca um canal seguro sobre o TCP. Ele prova a identidade do servidor com um certificado, combina chaves novas e depois criptografa e autentica tudo o que é enviado. HTTPS, e-mail seguro e muitos outros protocolos rodam dentro dele. SSL era o nome do seu antecessor.",Sits:"Fica","Between TCP and the app":"Entre o TCP e o app","OSI layer":"Camada OSI","Often placed at 6":"Muitas vezes posto na 6",Current:"Atual",Retired:"Aposentados","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 e 3, TLS 1.0 e 1.1","The app’s own (443, 993 …)":"A do próprio app (443, 993 …)","Secure from start to finish":"Seguro do início ao fim","One round trip to set up":"Uma ida e volta para estabelecer","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Uma ida e volta bastou para combinar uma versão, uma cifra e uma chave híbrida pós-quântica. A cadeia de certificados provou quem era o servidor, e cada byte depois do Server Hello foi criptografado e autenticado, até o close_notify. Pressione REPETIR para ver de novo.","1 round trip":"1 ida e volta","Everything the browser supports":"Tudo o que o navegador suporta","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Depois do handshake TCP, o navegador lista o que sabe fazer: versões de TLS, conjuntos de cifras e partes de chave para os grupos que espera, incluindo o híbrido pós-quântico X25519MLKEM768. Ele também nomeia o site (SNI) e os protocolos que fala (ALPN).",Versions:"Versões","versions, ciphers, key shares":"versões, cifras, partes de chave","Choices made, keys computed":"Escolhas feitas, chaves calculadas","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"O servidor escolhe o TLS 1.3, o conjunto de cifras e o grupo híbrido, e envia a sua própria parte da chave. A partir das duas partes, os dois lados calculam o mesmo segredo sem que ele jamais atravesse a rede. Tudo depois desta mensagem é criptografado.",Group:"Grupo","From here on":"Daqui em diante","its key share":"sua parte da chave",Certificate:"Certificado","Who the server is, proven":"Quem é o servidor, comprovado","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Já criptografado, o voo continua: o protocolo escolhido (http/1.1), a cadeia de certificados, uma assinatura feita com a chave privada do certificado e o Finished.",Chain:"Cadeia","Site → intermediate → root":"Site → intermediário → raiz","Proves the private key":"Prova a chave privada",Checked:"Verificado","Name, dates, trusted root":"Nome, datas, raiz confiável","encrypted: http/1.1, certificates,":"criptografado: http/1.1, certificados,","signature, Finished":"assinatura, Finished","One round trip, then data":"Uma ida e volta, depois os dados","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"O navegador envia o seu próprio Finished: um valor de verificação sobre tudo o que os dois lados disseram, calculado com o novo segredo, de modo que qualquer adulteração dos hellos apareceria. O TLS 1.3 precisa de uma ida e volta antes de os dados fluírem; o TLS 1.2 precisava de duas.",Covers:"Abrange","The whole handshake":"O handshake inteiro","For old middleboxes":"Para middleboxes antigos","check value over":"valor de verificação sobre","the whole handshake":"o handshake inteiro","Encrypted Data":"Dados criptografados","Records, tags and tickets":"Registros, tags e tickets","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"O HTTP agora viaja em registros criptografados, cada um com uma tag de 16 bytes que revela qualquer alteração. O servidor também envia dois tickets de sessão: da próxima vez o navegador pode retomar com um deles e pular o certificado.","Per record":"Por registro","22 bytes of overhead":"22 bytes de sobrecarga","2, for resuming later":"2, para retomar depois",Visible:"Visível","IPs, SNI, sizes, timing":"IPs, SNI, tamanhos, tempos","2 session tickets":"2 tickets de sessão","for resuming later":"para retomar depois",Closing:"Encerramento","close_notify, then TCP":"close_notify, depois o TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Depois de 75 segundos sem atividade, o servidor fecha a conexão. Primeiro envia um alerta close_notify, criptografado como todo o resto, para o navegador saber que os dados terminaram de propósito e não foram cortados por um atacante. Depois o TCP fecha como de costume.",Alert:"Alerta","Shows nothing was cut off":"Mostra que nada foi cortado","TCP FIN from both sides":"TCP FIN dos dois lados","alert: close_notify":"alerta: close_notify",encrypted:"criptografado","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ criptografado)","Encrypted handshake (continued)":"Handshake criptografado (continuação)","Encrypted handshake (certificate, verify, Finished)":"Handshake criptografado (certificado, verificação, Finished)","Application Data (inside: close_notify alert)":"Application Data (dentro: alerta close_notify)","Alert: close_notify (the data ends here, on purpose)":"Alerta: close_notify (os dados terminam aqui, de propósito)","No IP address":"Sem endereço IP","192.168.1.1 · DHCP server":"192.168.1.1 · servidor DHCP"},s=o=>`${o} ${o==="1"?"registro":"registros"}`,c={strings:{...i,...n},patterns:[[/^[\d,]+ bytes$/,"$&"],[/^(Ethernet II|IPv4|UDP|TCP) · \d+ bytes$/,"$&"],[/^(Application Data|Handshake|Change Cipher Spec), [\d,]+ bytes?$/,"$&"],[/^[\d,]+ bytes: report\.pdf, bytes .+$/,"$&"],[/^(.+) h later$/,"$1 h depois"],[/^(.+) min later$/,"$1 min depois"],[/^(.+) s later$/,"$1 s depois"],[/^(\S+) \(relative\)$/,"$1 (relativo)"],[/^(\d+) \(ephemeral\)$/,"$1 (efêmera)"],[/^(\d+) TCP segments$/,"$1 segmentos TCP"],[/^(\d+) segments$/,"$1 segmentos"],[/^(.*), (\d+) segments$/,"$1, $2 segmentos"],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(o,e,a,r)=>`TLS 1.3 · ${s(e)} · bytes ${a} de ${r}`],[/^TLS 1\.3 · (\d+) records?$/,(o,e)=>`TLS 1.3 · ${s(e)}`],[/^Ethernet padding · (\d+) bytes$/,"Preenchimento Ethernet · $1 bytes"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 bytes zerados, até o mínimo de 300 bytes"],[/^(\d+) zero bytes$/,"$1 bytes zerados"],[/^(\d+) random bytes$/,"$1 bytes aleatórios"],[/^Seen as it leaves (.+)$/,"Visto ao sair de $1"],[/^Option (\d+)$/,"Opção $1"],[/^value (\d+), echo (\d+)$/,"valor $1, eco $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 bytes, mais $1 de opções."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"O Windows começa em $1. Aqui foi definido como $2 de propósito."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(o,e,a)=>a==="1"?`Começou em ${e}; o roteador no caminho tirou 1.`:`Começou em ${e}; cada um dos ${a} roteadores no caminho tirou 1.`],[/^all (\d+) bytes of it$/,"todos os seus $1 bytes"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"O pacote que causou isto, como o dispositivo que avisa o recebeu (TTL $1), para o remetente saber de qual pacote se trata."],[/^Port (\d+), TLS from the start$/,"Porta $1, TLS desde o início"],[/^(\d+), TLS from the start$/,"$1, TLS desde o início"]],post:t};export{c as default};
